def recover_legacy_contacts(apps, schema_editor):
    Report = apps.get_model("reports", "Report")
    for report in Report.objects.using(schema_editor.connection.alias).all().iterator():
        changed = []
        # Older submissions stored contacts in description instead of dedicated fields.
        if not report.reporter_email:
            match = re.search(r"^Reporter Email: ([^\r\n]+)$", report.description, re.MULTILINE)
            if match:
                email = match.group(1).strip()
                try:
                    validate_email(email)
                except ValidationError:
                    pass
                else:
                    if len(email) <= 254:
                        report.reporter_email = email.lower()
                        changed.append("reporter_email")
        if not report.reporter_phone:
            match = re.search(r"^Reporter Phone: ([^\r\n]+)$", report.description, re.MULTILINE)
            if match and len(match.group(1).strip()) <= 20:
                report.reporter_phone = match.group(1).strip()
                changed.append("reporter_phone")
        if changed:
            report.save(using=schema_editor.connection.alias, update_fields=changed)


